        },
        {
          "text": "Yes. A 1 in 2 chance requires exactly 50 white flowers.",
          "isCorrect": false,
          "reason": "You are treating a chance for each seed as a guarantee for the whole batch. The count can vary.",
          "picture": null
        },
        {
          "text": "Yes. The result proves the chance was 47 in 100.",
          "isCorrect": false,
          "reason": "You are treating one batch's result as the exact chance. A batch can differ from its prediction by chance.",
          "picture": null
        }
      ],
      "image": null,
